// Ayuda en español – mismas secciones/ids/imágenes que static/hilfe.js
const K = (t) => `<kbd>${t}</kbd>`;
const HILFE = [
  ['start', 'Primeros pasos', ['dashboard'], `
    <p>El <b>Command Center</b> gestiona tu servidor Linux desde el navegador: carga, Docker, máquinas virtuales, terminal,
    usuarios y seguridad, todo en un sitio, en claro y oscuro, en el móvil y en el PC.</p>
    <ul>
      <li><b>Inicia sesión</b> con un usuario Linux del servidor (o con una contraseña propia del Command Center, ver «Mi cuenta»).</li>
      <li><b>Navegación:</b> barra lateral a la izquierda (abajo en el móvil); ${K('⌘/Ctrl')} + ${K('K')} abre «Ir a …» para páginas, contenedores y servicios.</li>
      <li><b>Lo que ves depende de tus permisos.</b> Los superadministradores lo ven todo; los demás, solo las páginas de sus grupos.</li>
      <li><b>Ayuda de la página actual:</b> tecla ${K('?')}.</li>
      <li><b>Idioma:</b> Ajustes → Idioma (también en la página de inicio de sesión): Deutsch, English, Español. Tu cuenta lo recuerda en todos los dispositivos.</li>
    </ul>`],
  ['uebersicht', 'Resumen', ['dashboard'], `
    <p>Indicadores (CPU, memoria, red, discos) con un mini historial y, debajo, gráficos de los últimos 15 minutos hasta 24 horas.</p>
    <ul><li>Gráficos: señalar muestra los valores, arrastrar hace zoom, la leyenda oculta series, «Tabla» muestra los números.</li>
    <li>Tocar un mosaico salta al gráfico correspondiente.</li></ul>`, 'uebersicht'],
  ['system', 'Procesos, servicios, actualizaciones', ['processes', 'services', 'updates'], `
    <ul><li><b>Procesos:</b> ordenables, terminar un proceso (permiso «Terminar procesos»).</li>
    <li><b>Servicios:</b> buscar, iniciar, detener y reiniciar servicios de systemd.</li>
    <li><b>Actualizaciones:</b> actualizaciones de paquetes pendientes, se instalan cuando quieras.</li></ul>`],
  ['terminal', 'Terminal y pestañas', ['terminal'], `
    <p>Una shell real en el servidor. Cada pestaña es una sesión propia que <b>sigue en marcha</b> —aunque cierres la página
    o el Command Center se reinicie— hasta que cierres la pestaña o escribas ${K('exit')}.</p>
    <table><tr><td>${K('Alt')} + ${K('T')}</td><td>nueva terminal</td></tr>
    <tr><td>${K('Alt')} + ${K('1')}…${K('9')}</td><td>ir a la pestaña 1–9</td></tr>
    <tr><td>${K('Alt')} + ${K('⇧')} + ${K('←/→')}</td><td>mover la pestaña activa</td></tr>
    <tr><td>Doble clic / clic derecho / ⋯</td><td>ajustes: nombre, fijar, posición, cerrar</td></tr>
    <tr><td>Clic central</td><td>cerrar pestaña</td></tr></table>
    <ul><li><b>Fijar:</b> la pestaña se queda delante y no tiene ×.</li>
    <li><b>Arrastrar</b> mueve pestañas; el botón junto a «+» pone las pestañas <b>al lado</b> (se guarda por usuario).</li>
    <li><b>Quien no es superadministrador</b> recibe la shell como su propio usuario Linux, sin <code>sudo</code>/<code>su</code> (bloqueado técnicamente).</li>
    <li>Copiar: ${K('Ctrl')} + ${K('⇧')} + ${K('C')}, pegar: ${K('Ctrl')} + ${K('⇧')} + ${K('V')}.</li></ul>`],
  ['docker', 'Docker', ['docker', 'docker-detail'], `
    <ul><li><b>Contenedores:</b> estado, CPU/RAM en vivo, iniciar/detener/reiniciar, logs (en vivo), consola, archivos, procesos, inspect.</li>
    <li><b>Al abrir un contenedor</b> aparecen arriba cuatro mosaicos en vivo (cada segundo) y en la pestaña «Stats», gráficos de los últimos 5 minutos.</li>
    <li><b>Imágenes, redes, volúmenes, stacks</b> (proyectos de Compose), <b>sistema</b> (espacio, limpieza).</li>
    <li>Permisos: «Ver Docker», «Iniciar/detener contenedores», «Gestionar Docker» (⚠ equivale a root).</li></ul>`, 'docker'],
  ['vms', 'Máquinas virtuales', ['vms', 'vm-detail'], `
    <p>libvirt/KVM: crear e iniciar VMs, consola en el navegador (VNC/SPICE), instantáneas, dispositivos, redes, ISOs.
    Quien tiene el permiso «Máquinas virtuales propias» solo ve y maneja sus propias VMs (el nombre empieza por su prefijo) y las compartidas.
    Sin libvirt en el servidor la página queda vacía; todo lo demás funciona con normalidad.</p>`],
  ['zugriff', 'Conexiones y navegador', ['connections', 'browser'], `
    <ul><li><b>Conexiones:</b> guarda SSH/VNC/RDP a otros equipos y ábrelos en el navegador.</li>
    <li><b>Navegador:</b> sesiones de navegador aisladas en un contenedor, p. ej. para sitios que no quieres abrir en tu propio navegador.</li></ul>`],
  ['sicherheit', 'Seguridad y bloqueos', ['security'], `
    <ul><li><b>Vigilante IDS</b> (Suricata): tráfico, alertas, últimos bloqueos, en vivo.</li>
    <li><b>IPs bloqueadas:</b> por fail2ban, por el IDS y a mano; bloquear/desbloquear (también varias); el bloqueo se aplica en el firewall y, si está configurado, en el borde de Cloudflare.</li>
    <li><b>Mensajes:</b> intentos fallidos, bloqueos, inicios de sesión; filtra por aplicación, origen y texto.</li>
    <li>Qué partes funcionan lo eliges al instalar (módulos, ver Preguntas frecuentes). Sin fail2ban, el IDS bloquea por sí mismo.</li></ul>`, 'sicherheit'],
  ['angriffe', 'Ataques (radar de ataques)', ['angriffe'], `
    <p>Recopila intentos de ataque cada 2 minutos: búsquedas de secretos (<code>.env</code>, <code>.git</code> …), escaneos de vulnerabilidades y
    exploits, inicios de sesión erróneos y alertas IDS; 24 h / 7 / 30 días, origen, objetivos, rutas buscadas.</p>
    <ul><li><b>Bloqueo automático</b> (con fail2ban): 3 escaneos en una hora o 1 intento de exploit → bloqueado (1 día, más si se repite).</li>
    <li>El tráfico normal no se guarda, solo los intentos (90 días).</li></ul>`, 'angriffe'],
  ['benutzer', 'Usuarios, grupos y permisos', ['users'], `
    <p>Los permisos se conceden mediante <b>grupos</b>; un usuario puede estar en varios. La vista «Resumen» muestra en una tabla quién puede hacer qué.</p>
    <ul><li><b>24 permisos</b> en cinco áreas; los marcados con ⚠ son críticos (prácticamente root o acceso a secretos).</li>
    <li><b>Plantillas:</b> observador, cuidador de Docker, administrador de Docker, administrador del sistema, seguridad, usuario de VM, gestión de usuarios, herramientas, gestor de contraseñas, «Todos los usuarios con sesión».</li>
    <li><b>Las contraseñas de otros usuarios</b> solo las establece el <b>propietario</b> (un superadministrador designado).</li>
    <li>«Gestión de usuarios» solo puede asignar grupos cuyos permisos tenga ella misma. Las cuentas de servicio de los programas están protegidas.</li>
    <li>El servidor comprueba cada permiso en cada acción; el menú solo oculta.</li></ul>`, 'benutzer'],
  ['benachrichtigungen', 'Notificaciones', ['notifications'], `<p>Mensajes de ntfy (p. ej. bloqueos, inicios de sesión, avisos del servidor) para leerlos después.</p>`],
  ['werkzeuge', 'Páginas opcionales', ['konten', 'codes', 'backups', 'werkzeuge', 'startseite', 'automationen'], `
    <p>Cuentas, códigos, copias de seguridad, herramientas IT, Mi panel y automatizaciones solo existen si el servidor los incluye en
    <code>funktionen.json</code>. Las apps incrustadas funcionan en un sandbox sin acceso al Command Center.</p>`],
  ['einstellungen', 'Ajustes, licencia y mi cuenta', ['settings', 'konto'], `
    <ul><li><b>Idioma</b> y apariencia (claro/oscuro).</li>
    <li><b>Licencia</b> (superadministradores): estado, válida hasta, introducir una clave nueva. Si caduca pronto, aparece un aviso arriba.</li>
    <li><b>Pestañas visibles:</b> oculta páginas de tu barra lateral (los permisos no cambian).</li>
    <li><b>Acceso SSH predeterminado</b> para conexiones. <b>Base de datos:</b> estado de la caché rápida (PostgreSQL con réplica, alternativa SQLite).</li>
    <li><b>Mi cuenta:</b> imagen de perfil, cambiar contraseña, correo para «¿Olvidaste la contraseña?», cerrar sesión en los demás dispositivos.</li></ul>`, 'einstellungen'],
  ['tasten', 'Todos los atajos de teclado', [], `
    <table><tr><td>${K('⌘/Ctrl')} + ${K('K')}</td><td>Ir a … (páginas, contenedores, servicios, acciones)</td></tr>
    <tr><td>${K('⌘/Ctrl')} + ${K('B')}</td><td>plegar/desplegar la barra lateral</td></tr>
    <tr><td>${K('?')}</td><td>ayuda de la página actual</td></tr>
    <tr><td>${K('Alt')} + ${K('T')} / ${K('1')}…${K('9')}</td><td>terminal: nueva pestaña / cambiar de pestaña</td></tr>
    <tr><td>${K('Esc')}</td><td>cerrar ventanas y búsqueda</td></tr></table>`],
  ['faq', 'Preguntas frecuentes', [], `
    <details><summary>¿Cómo actualizo el Command Center?</summary><p>En el servidor: <code>sudo command-center update</code>. Los ajustes, usuarios y datos se conservan. Hace falta una licencia válida.</p></details>
    <details><summary>¿Cómo cambio lo que está instalado (fail2ban, IDS, copias …)?</summary><p><code>sudo command-center module</code> muestra los módulos; <code>sudo command-center module +postgres -ids</code> añade PostgreSQL y quita el IDS. Módulos: fail2ban, ids, firewall, radar, cloudflare, ntfy, postgres, backup. El IDS también funciona sin fail2ban: entonces bloquea por sí mismo.</p></details>
    <details><summary>Me he bloqueado a mí mismo (mi IP está bloqueada).</summary><p>Inicia sesión desde otra conexión (p. ej. el móvil sin wifi) y usa «Desbloquear mi IP» en <b>Seguridad y bloqueos</b>, o por SSH: <code>sudo waechter freigeben &lt;IP&gt;</code>. Para que no vuelva a pasar: añade tus IPs a <code>TRUSTED_IPS</code> en <code>/etc/linux-dashboard/schutz.conf</code>.</p></details>
    <details><summary>He olvidado mi contraseña.</summary><p>Usa «¿Olvidaste la contraseña?» en la página de inicio de sesión (requiere un correo confirmado en «Mi cuenta»). Si no, por SSH: <code>sudo passwd &lt;usuario&gt;</code>. En el Command Center solo el propietario establece contraseñas de otros.</p></details>
    <details><summary>¿Cómo hago accesible el Command Center desde fuera de forma segura?</summary><p>Nunca lo expongas sin protección: tiene derechos de root. Lo más sencillo es una VPN (Tailscale, WireGuard) o un proxy inverso HTTPS o Cloudflare Tunnel con control de acceso. Quién puede conectarse directamente se define en <code>/etc/linux-dashboard/dashboard.env</code> (<code>DASHBOARD_ALLOWED_NETS</code>).</p></details>
    <details><summary>¿Dónde veo mi licencia y qué pasa cuando caduca?</summary><p>En <b>Ajustes → Licencia</b> (o <code>sudo command-center lizenz</code>). 30 días antes aparece un aviso. Tras caducar, el Command Center sigue funcionando, pero las actualizaciones quedan bloqueadas hasta que la renueves: introduce una clave nueva en Ajustes. Solicitar y renovar: <a href="https://lizenz.slxt.dev/?lang=es" target="_blank" rel="noopener">lizenz.slxt.dev</a>.</p></details>
    <details><summary>¿Cómo hago copias de seguridad y las restauro?</summary><p>Con el módulo <b>backup</b>, el servidor guarda cada noche ajustes y datos en <code>/var/backups/command-center</code> (14 días). A mano: <code>sudo command-center backup</code>; listar: <code>… backup --liste</code>; restaurar: <code>… backup --zurueck &lt;archivo&gt;</code>.</p></details>
    <details><summary>¿Por qué no funciona <code>sudo</code> en la terminal?</summary><p>Quien no es superadministrador recibe a propósito una shell sin derechos de root. Los superadministradores se definen con <code>DASH_SUPERADMINS</code> en <code>/etc/linux-dashboard/dashboard.env</code>.</p></details>
    <details><summary>¿Cuántos recursos necesita el Command Center?</summary><p>El Command Center en sí, unos 100–200 MB de RAM. El IDS (Suricata) necesita 1–2 GB: con poca RAM, prescinde del módulo <b>ids</b>.</p></details>
    <details><summary>¿Dónde están los ajustes y los datos?</summary><p>Ajustes: <code>/etc/linux-dashboard/</code> (<code>dashboard.env</code>, <code>schutz.conf</code>, <code>module.conf</code>). Datos: <code>/var/lib/linux-dashboard/</code>. Programa: <code>/opt/command-center</code>.</p></details>
    <details><summary>¿Cómo elimino el Command Center?</summary><p><code>sudo command-center deinstallieren</code>: los datos se quedan; con <code>--alles</code> también se eliminan datos, ajustes y el paquete de protección (fail2ban/IDS/firewall).</p></details>`],
  ['probleme', 'Si algo no funciona', [], `
    <ul><li><b>«Te falta el permiso …»</b>: un superadministrador puede concedértelo en Usuarios → Grupos.</li>
    <li><b>La página no carga / vista antigua:</b> recarga (${K('⌘/Ctrl')} + ${K('⇧')} + ${K('R')}).</li>
    <li><b>Terminal desconectada:</b> «Nuevo» reconecta; la sesión sigue en marcha.</li>
    <li><b>Base de datos «SQLite» en vez de PostgreSQL:</b> el contenedor de la base de datos no es accesible; todo sigue funcionando, estado en Ajustes.</li>
    <li><b>Logs:</b> <code>sudo command-center logs -f</code>; estado: <code>sudo command-center status</code>.</li></ul>`],
];

